from scipy.optimize import least_squares
def res(p, kind):
    q,r,pe=p
    cols=[1/t, t**q*A**r]
    if kind=='pow': cols.append(A**pe)
    X=np.c_[cols].T
    c,_,_,_=np.linalg.lstsq(X,dA_dt,rcond=None)
    return X@c-dA_dt
